core=[]
def K(title,c):
 c['path']='木兰花全集/'+title+'.txt';core.append(c)
def E(title,a,b,s):return ('木兰花全集/'+title+'.txt',a,b,s)
def A(name,kind,mechanism,visual,apps,limits):return dict(name=name,type=kind,mechanism=mechanism,visual=visual,applications=apps,limits=limits)
K('07高原之谜',C('ma_chaowen','马超文','马超文生在马多禄的富裕家庭，却不愿照父亲安排生活，在国外学地质，宁可半工半读，也不要家里寄钱。他与挥霍生事的哥哥马超武不同，参加南美高原探险首先出于求知，幸存归来后却被惊恐与一条满是钻石的小溪的记忆缠住。他拒绝轻易相信别人说自己只是患病，暗中查阅地理矿物书、找人求证，又因此落入争夺财富的绑架链。穆秀珍最初对他的家世有成见，两人在囚禁、追逃和攀崖中相互护持，他会害怕、缺少跳伞经验，却仍试图站在她前面挡住威胁。重新抵达高原，所谓钻石原来是阳光照在水泡上的幻景；他尴尬，却和穆秀珍一起承认真情比虚幻财富珍贵。恋爱后，他多次在医院或秘密疗养地点照顾受伤的她，紧张时会忘了保持安静，听她开口又能含泪笑起来。他后来学业完成，得到海外企业高级工程师聘书，准备归来正式订婚，却在班机遭破坏爆炸时遇难。穆秀珍以他的名字纪念新炼油法，那不是他本人发明的技术。终局回溯保留一位青年研究者、爱人和遇难者的经历，不把他补写成拥有所有工程学与武术的万能科学家。','在22《天外恩仇》归国班机爆炸中死亡，未来聘任和正式订婚未能实现。','年轻、略带倔强的地质研究者；惊险和恋人受伤时会流露紧张与哀痛。','凭自己的学习和行动立身，追求真实知识并保护所爱。','先坚持亲历判断，证据揭示错误后会羞惭；亲近者受伤时主动留下照料。','地质学习、野外观察、有限攀援与普通照料；缺乏专业战斗和跳伞训练。',[E('07高原之谜',50,110,'求学、独立及探险'),E('07高原之谜',1664,1676,'护穆行动'),E('07高原之谜',1798,1804,'无跳伞经验'),E('07高原之谜',2454,2488,'幻景真相与感情选择'),E('12夺命红烛',730,750,'医院焦急'),E('15杀人奖金',1582,1632,'秘密疗养照护'),E('22天外恩仇',14,98,'聘任、订婚计划和遇难'),E('22天外恩仇',2694,2726,'后人命名纪念')],[('自己的亲历与常识冲突','尚能找到原地点或记录','坚持核验而非立即认错，也不把记忆当最终证据。'),('家族财富可替自己安排道路','有独立学习工作的机会','倾向用劳动证明能力，可能与父亲争执。'),('爱人受伤而战斗已交他人处理','自己能留下照料','陪伴、安抚和配合医生，不为面子强上前线。')],roles=['主角','重要配角'],revive=True,limits='未真正就任海外高级工程师；超文炼制法是纪念命名，不是他的技术。高原钻石为误认，不保留矿产财富。',reasons={'physical':'能参与野外行动和攀援，但没有专业近战表现。','energy':'没有非物理攻击。','scope':'只作用于自身和近旁个体。','sustain':'正常青年体力，危险环境仍需协助。','range':'没有常备远程武器证据。','combat':'照料与学术作用不换算为武斗力。'}))
K('07高原之谜',C('ma_duolu','马多禄','马多禄是本市大企业家，经营重工业、建筑、交通、航空与报纸，习惯自己的身份让旁人让路。他面对次子马超文从高原归来后的异常，却发现钱财不能让儿子恢复沟通，只能与妻子亲自到木兰花门前求助。说出请教一词令他别扭，包机救子之后又提起昂贵费用，保留了把资源当作解决问题主要手段的惯性。两个儿子的差异使他的父爱并不总公正：他能承认超文勤奋、超武没出息，仍在绑架证据出现时替长子否认，等长子认罪，又先愤怒要打，再暗示可用一大笔现金通融。高翔斥其行贿，他竟因儿子可能入狱昏倒，醒后仍跟去设法。后来次子学成回国、将与穆秀珍正式订婚，他以航空公司董事长身份带家人去接机，迎来的却是班机失联与毁灭的消息。他挥着手杖冲进办公室，不再有平时的从容，财富不能换回罹难者。综合终局，他既是真心爱子的父亲，也是惯于越过规则庇护家人的权势者。卡片不替他虚构悔改完毕或公司破产，更不把商业网络变成随时能调动军队、查到所有秘密的能力。','次子马超文在22班机爆炸中遇难；马多禄本人未写死亡或失去企业。','肥胖的中老年富商，常带手杖，急迫时脸部肌肉颤动。','保护家庭及其体面，尽力用自己熟悉的资源解决危机。','先调关系与钱，家人可能受罚或遇难时会失态。','经营资源、包机、求援及组织联络；无独立武斗或超常技术。',[E('07高原之谜',24,60,'产业外观与求助'),E('07高原之谜',98,112,'父子分歧和包机'),E('07高原之谜',976,1012,'护长子、行贿暗示与昏倒'),E('22天外恩仇',42,82,'机场身份与惊惶')],[('家人的难题不能直接花钱消除','仍有可信专家可求','会压下身段求助，但可能反复强调花费。'),('亲人涉嫌违法','证据尚未迫到眼前','先本能辩护，证据确凿后仍可能试图通融。'),('企业权力遇到不可逆灾难','所爱生命已经受威胁','从颐指气使转为慌乱，不再维持成功者体面。')],roles=['重要配角','阶段性对立者'],aliases=['马绅士','马董事长'],limits='公司资源需真实所在地、人员与业务条件；身体并无防弹或武术证据。未把一次行贿暗示当已成功操纵司法。'))
K('07高原之谜',C('mrs_ma','马夫人','马夫人没有独立给出的名字，是马多禄的妻子、马超文与马超武的母亲。她随丈夫到木兰花家求助时，穿戴显示富裕，手上满是钻戒，却顾不上体面，抓住刚认识的女侠的手便哭着请她救儿子。她比丈夫更直接地用情绪表达恐惧，把超文归来后的异常说成疯了，又承受解释不清、被旁人误认成另一儿子的窘迫。调查过程中，超文失踪、家人说法互相推翻，木兰花有时也要当面修正先前判断；马夫人所能做的不是立刻破案，而是在反复希望与失望间等待，愿意让能调查的人继续介入。与长子的放纵相比，她在次子的感情生活里留下的是另一面：正式接机订婚的那天，亲友的目光使穆秀珍不自在，她却对未来儿媳十分友善，让穆在与父母同车时稍能放松。随后飞机失联，她的尖叫和夫妻一起冲往办公室的行动，把喜庆准备瞬间变成无法掌控的灾难。终局次子遇难，她本人仍在，原文未细写长期哀伤的走向。演绎应让她保有母亲的依恋和对亲近年轻人的温和，不能只用富家太太标签替代，也不能将她未参与的行贿自动记到她头上。','22接机时得知次子所乘班机遇难；本人后续未单独交代。','体态丰腴、手戴钻戒的富家夫人；焦虑时握紧求助者的手、落泪或尖叫。','守护儿子并维系家庭的亲近感。','倾向直接求援、表达担心；恐惧会使措辞绝对化。','普通人的家庭照料、交往与求助；未显示特殊战斗手段。',[E('07高原之谜',30,68,'外貌、求助和母亲身份'),E('07高原之谜',422,430,'等待与调查者修正判断'),E('22天外恩仇',20,26,'友善接纳穆'),E('22天外恩仇',54,82,'失联消息和机场反应')],[('家人行为突然陌生','自己无法理解原因','用自己的语言描述恐惧，并主动寻找能帮助的人。'),('未来的家庭成员在亲友面前拘束','自己能给予小范围支持','以友善态度缓和气氛，不要求她立刻符合全部礼数。'),('收到可能失去孩子的消息','事实还在核查','会急切追问并失态，不能被一句有钱就能解决安抚。')],roles=['重要配角'],aliases=['马多禄夫人','马老太'],limits='不因婚姻身份继承马多禄全部经营技能或权力，也不替她承担丈夫单独实施的行贿行为。'))
K('02黑龙现爪',C('sadula','萨都拉','萨都拉是阿拉伯某国的政治与军事要人，也是阿敏娜的父亲。他初到本市时重伤住院，女儿被黑龙党绑走，使这个习惯担当的人承认自己有无法冷静计算的弱点。他接受方局长让高翔假扮自己的救援计划，女儿获救后又亲自聘用拒绝杀人的彭可作保姆，愿把真实的保护行动看得比旧标签更重。回国途中，黑龙党劫持客机，他为了其他旅客主动跳伞接受控制，又因女儿牵住双腿而迟疑；勇敢并没有消去亲情。与木兰花脱离潜艇、海上求生时，他能持枪、游泳、拳击，也会节制饮水，处理有限资源。后来他发现自己深信的卡基总理竟是黑龙党头领，悲愤到向尸旁乱枪发泄，仍在同伴提醒下驾机脱离火场、回去主持善后，并成为总理。面对超人集团，他明知本国有限海军与敌方技术差距巨大，仍提供舰艇、借来的探测仪和实际协作；那是政治责任与私人信任共同促成的选择，并非一句话就有无限舰队。他对木兰花有明显情意，面对女儿揭露时也会窘迫，但不能据此宣布双方婚恋。终局仍为有责任、会受友情牵动的国家领导者，国家和人民不是随身道具。','在03成为总理；06及24仍以国家领导者身份协助，未写死亡、退位或与木兰花结合。','面容庄严、体格强健、目光有神的阿拉伯成年男子，情急时声音洪亮。','守护女儿与国家，回报共同历险者的信任。','能承担风险，也会因背叛、亲人受威胁而失去从容；接受可信同伴纠正。','普通人的武装行动、游泳、驾驶飞机与政治军事协调；支援有国家实力和程序条件。',[E('02黑龙现爪',162,184,'受伤父亲与营救决策'),E('02黑龙现爪',1848,1852,'聘彭可'),E('03太阳之女',6,62,'主动承担客机危机'),E('03太阳之女',568,658,'枪械、脱艇、拳击与饮水'),E('03太阳之女',1648,1668,'悲愤、驾驶与任总理'),E('06超人集团',1984,2108,'援助、情感与实力自知'),E('06超人集团',2126,2164,'有限舰队实际部署'),E('24魔掌余生',286,292,'协调发掘许可')],[('所爱被拿作要胁','公职责任与亲情发生冲突','先求可信者协作，无法保证完全冷静。'),('个人牺牲能减少无辜伤亡','有实际可执行的交换方案','倾向亲自承担，但会认真安排家人后路。'),('朋友请求国家资源','风险与本国能力都已说明','衡量后作明确有限承诺，不凭热情变出不存在的力量。'),('旧盟友以国家名义谋私','已有可靠证据','悲愤可能先于理性，随后仍须处理善后。')],roles=['重要配角'],scores=GUN,tier='并',limits='国家舰队不等个人常备武器，06明确海军力量有限且探测仪需借邻国。无心灵控制、神佑免伤或不死。',uncertainties=['02称妻已死，03又有送女儿回母亲处的说法，语料家庭背景矛盾，保留而不补婚姻史。','早期官职有内政、军事描述，确定的是03终局任总理；不据此锁定现实国家。'],reasons={'physical':'能拳击、游泳和武装行动，仍为可受重伤的人体。','energy':'没有超常能量攻击。','scope':'个人武器只作用局部；国家政治影响不当物理范围。','sustain':'有实战和海上行动能力，需水与常规休息。','range':'按实际枪械战斗计，舰队需单独部署。','combat':'能参加近战和枪战并指挥，未展示超人毁伤。'}))
K('02黑龙现爪',C('amina','阿敏娜','阿敏娜是萨都拉的女儿，长发、圆脸、大眼睛，面对成人世界的政治阴谋仍保有直接而具体的感情。黑龙党绑架她，是想控制父亲，她却没有把身边的彭可只看成敌人的工具。听到金星命令保姆杀自己，她问的是对方是否不愿再与自己在一起；此前的相处让这句话有了重量，也使木兰花的劝说找到真正的关系基础。被救出来以后，她要求带彭可一同见父亲，见对方因旧罪觉得不配，便请她蹲下，在脸上亲吻，明确认她作朋友。这样的亲近改变的是一个人的选择，不是强制感化所有恶人的精神力量。回程客机再遇袭，她抱住父亲的双腿，知道他要离开时哭泣，依然需要大人保护。后来木兰花去拜访，她认出亲近的阿姨便拥抱，想替男装的客人打扮，还差点说出父亲的私密心事，被喝止后停下。到穆秀珍丧失未婚夫时，她从远方寄出自己做的慰问卡，用孩子画出的哭脸和俏皮话让悲痛者重新笑起来。综合终局的她既受过恐惧，也会把获得的关怀传给别人；她不是永远等待救援的奖品，更不因父亲是总理就拥有成人的权谋和武力。','早期绑架中获救，之后继续与父亲生活；22以自制慰问卡支持穆秀珍，未写死亡或成年变化。','长发、圆脸、大眼的阿拉伯女孩，情绪常直接写在脸上。','与父亲和可信的朋友保持亲近，也希望别人不要只剩悲伤。','害怕时抱住亲人，表达依恋；能用质朴问题让照料者重新看见关系。','普通儿童的观察、交谈和自制慰问表达；无战斗、心灵或超常防护。',[E('02黑龙现爪',1752,1754,'被威胁时的直接问话'),E('02黑龙现爪',1796,1828,'救出、认彭可为友与亲吻'),E('03太阳之女',12,62,'客机危机与父女离别'),E('06超人集团',2064,2084,'外貌、拥抱与家庭互动'),E('22天外恩仇',220,228,'自制慰问卡')],[('熟悉的照料者奉命伤害自己','双方此前确有相处感情','直接询问对方是否还在意自己，不能保证奏效。'),('亲人要去承担危险','自己没有同行能力','表达害怕、要求承诺，需要真实安置而非自动懂事。'),('远方朋友因失去所爱消沉','自己能寄信或做小物','用个人化、略顽皮的方式传达关心，不模仿成人训诫。')],roles=['重要配角'],limits='关怀能影响具体关系中的人，但不是魅惑或强制善化。总理的权力与卫队不是儿童随身战力。',uncertainties=['母亲在02与03的叙述矛盾，卡片不擅自补生死与再婚解释。']))
(P/'core_cards.raw.json').write_text(json.dumps(core,ensure_ascii=False,indent=2),encoding='utf-8')
